var e=[{id:`n_1`,type:`scene_change`,speaker:null,text:null,stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:null,R:null}}},{id:`n_2`,type:`dialog`,speaker:`GRENADE_TIDE_NULL_NULL`,text:{KOREA:`탁월한 선택을 하신 겁니다, 사장님. 이런 불꽃 같은 가슴 가진 사나이는 어디 가서 찾기 힘들죠. 어서 다른 직원들에게도 우리들의 뜨거운 동료애를 알려 줘야겠군요!`,JPN:`素晴らしい選択です、社長。ここまで熱い心を持った男はそうそう見つかるものじゃありません。早く社員たちにも私たちの熱い絆を教えてやらないと！`,ENG:`You've made an excellent choice, Boss. I bet you won't find anyone else as passionate as I am. I can't wait to go tell others what great friends we've become!`,TWN:`真是出色的選擇，老闆。上哪裡能找到我們這樣熱情如火的真男人呢，我們得去向其他員工展現我們的熱情才行！`},stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:{char_id:`GRENADE_TIDE_NULL_NULL`,face:`UNIT_IDLE`,hologram:!1},R:null}}}];export{e as default};